const rows = $input.all().map(item => item.json);

if (rows.length === 0) {
  return [];
}

rows.sort((a, b) => {
  const priorityA = a.priority ?? 100;
  const priorityB = b.priority ?? 100;

  if (priorityA !== priorityB) {
    return priorityA - priorityB;
  }

  return new Date(a.created_at) - new Date(b.created_at);
});

return [
  {
    json: rows[0]
  }
];

const q = $('Pick Next Plant').first().json;

return [
  {
    json: {
      queue_id: q.id,
      plant_id: q.plant_id,
      scientific_name: q.scientific_name,
      target_indication: q.target_indication,
      indication_context: q.indication_context,
      ema_source_url: q.ema_source_url,
      modules: q.modules,
      priority: q.priority
    }
  }
];

const job =
  $('Prepare EMA Job').first().json;

const indication =
  $('Lookup PubMed Indication').first().json;


// ============================================================
// 1. Botanical search terms
// ============================================================

// "Glycyrrhiza glabra L."
// -> "Glycyrrhiza glabra"
const scientificName =
  String(job.scientific_name ?? '')
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .join(' ');

// "Glycyrrhiza glabra"
// -> "Glycyrrhiza"
const genus =
  scientificName
    .split(/\s+/)[0] ??
  scientificName;


// ============================================================
// 2. Indication terms from database
// ============================================================

const rawTerms = [
  indication.display_name,

  ...(
    Array.isArray(indication.synonyms)
      ? indication.synonyms
      : []
  )
]
  .filter(Boolean)
  .map(term =>
    String(term)
      .trim()
      .toLowerCase()
  )
  .filter(Boolean);


// Remove duplicate phrases
const phraseTerms = [
  ...new Set(rawTerms)
];


// ============================================================
// 3. Generate broader indication keywords
//
// Exact phrases can fail in PubMed when the wording is not
// present verbatim. Therefore also search meaningful individual
// clinical terms.
//
// The AI screening step remains responsible for deciding
// whether the retrieved paper actually matches the indication.
// ============================================================

const stopWords = new Set([
  'with',
  'associated',
  'association',
  'and',
  'the',
  'for',
  'from',
  'into',
  'mild',
  'symptoms',
  'symptom',
  'treatment',
  'prevention',
  'prevent',
  'adults',
  'adult',
  'patients',
  'patient'
]);


const keywordTerms = phraseTerms
  .flatMap(term =>
    term
      .replace(/[^a-z0-9\s-]/gi, ' ')
      .split(/\s+/)
  )
  .map(term =>
    term.trim().toLowerCase()
  )
  .filter(term =>
    term.length >= 4 &&
    !stopWords.has(term)
  );


const indicationKeywords = [
  ...new Set(keywordTerms)
];


// ============================================================
// 4. Escape PubMed strings
// ============================================================

function escapePubMed(value) {
  return String(value)
    .replace(/"/g, '\\"');
}


// ============================================================
// 5. Plant query
//
// Retrieval is intentionally broader than screening.
//
// Scientific species name = preferred
// Genus = fallback so papers using a less precise botanical
// label are still retrieved.
//
// Species specificity is checked later by the AI screen.
// ============================================================

const plantQuery = [
  `"${escapePubMed(scientificName)}"[Title/Abstract]`,
  `"${escapePubMed(genus)}"[Title/Abstract]`
].join(' OR ');


// ============================================================
// 6. Indication query
//
// Use both:
// - exact phrases
// - individual clinically meaningful keywords
//
// Example for Liquorice:
// phrases:
//   "productive cough"
//   "cough with phlegm"
//
// keywords:
//   cough
//   cold
//   expectorant
//   productive
//   phlegm
// ============================================================

const phraseQuery = phraseTerms
  .map(term =>
    `"${escapePubMed(term)}"[Title/Abstract]`
  );


const keywordQuery = indicationKeywords
  .map(term =>
    `"${escapePubMed(term)}"[Title/Abstract]`
  );


const indicationQuery = [
  ...new Set([
    ...phraseQuery,
    ...keywordQuery
  ])
].join(' OR ');


// ============================================================
// 7. Review query
//
// IMPORTANT:
// Retrieve ordinary reviews as well.
//
// Whether a review qualifies as systematic clinical evidence
// is decided later by the Evidence Screening step.
// ============================================================

const reviewTypeQuery = [
  '"Review"[Publication Type]',
  '"Meta-Analysis"[Publication Type]',
  'systematic[sb]'
].join(' OR ');


const pubmedReviewQuery =
  `(${plantQuery}) AND ` +
  `(${indicationQuery}) AND ` +
  `(${reviewTypeQuery}) AND ` +
  `humans[MeSH Terms] AND ` +
  `hasabstract`;


// ============================================================
// 8. Trial query
// ============================================================

const trialTypeQuery = [
  '"Randomized Controlled Trial"[Publication Type]',
  '"Clinical Trial"[Publication Type]'
].join(' OR ');


const pubmedTrialQuery =
  `(${plantQuery}) AND ` +
  `(${indicationQuery}) AND ` +
  `(${trialTypeQuery}) AND ` +
  `humans[MeSH Terms] AND ` +
  `hasabstract`;


// ============================================================
// 9. Output
// ============================================================

return [
  {
    json: {

      ...job,

      pubmed_scientific_name:
        scientificName,

      pubmed_genus:
        genus,

      pubmed_indication_terms:
        phraseTerms,

      pubmed_indication_keywords:
        indicationKeywords,

      pubmed_review_query:
        pubmedReviewQuery,

      pubmed_trial_query:
        pubmedTrialQuery,

      // Compatibility with older downstream nodes
      pubmed_query:
        pubmedReviewQuery
    }
  }
];

const items = $input.all();

function getIds(item) {
  const ids = item?.json?.esearchresult?.idlist;

  return Array.isArray(ids)
    ? ids.map(String)
    : [];
}

function getQuery(item) {
  return String(
    item?.json?.esearchresult?.querytranslation ?? ''
  ).toLowerCase();
}

// ---------------------------------------------
// Identify review and trial search result
// ---------------------------------------------

const reviewItem = items.find(item => {
  const query = getQuery(item);

  return (
    query.includes('systematic') ||
    query.includes('meta-analysis')
  );
});

const trialItem = items.find(item => {
  const query = getQuery(item);

  return (
    query.includes('randomized controlled trial') ||
    query.includes('clinical trial')
  );
});

// ---------------------------------------------
// Extract IDs
// ---------------------------------------------

const reviewIds = getIds(reviewItem);
const trialIds = getIds(trialItem);

// Reviews first, then trials
const allIds = [
  ...reviewIds,
  ...trialIds
];

// Remove duplicates while preserving order
const uniqueIds = [
  ...new Set(allIds)
];

// Find duplicate PMIDs for QC
const duplicates = allIds.filter(
  (id, index) =>
    allIds.indexOf(id) !== index
);

// ---------------------------------------------
// PubMed total counts
// ---------------------------------------------

const reviewTotalCount = Number(
  reviewItem?.json?.esearchresult?.count ?? 0
);

const trialTotalCount = Number(
  trialItem?.json?.esearchresult?.count ?? 0
);

// ---------------------------------------------
// Return one item
// ---------------------------------------------

return [
  {
    json: {
      pubmed_review_total_count:
        reviewTotalCount,

      pubmed_trial_total_count:
        trialTotalCount,

      pubmed_review_ids:
        reviewIds,

      pubmed_trial_ids:
        trialIds,

      pubmed_review_retrieved:
        reviewIds.length,

      pubmed_trial_retrieved:
        trialIds.length,

      pubmed_duplicate_ids:
        [...new Set(duplicates)],

      pubmed_duplicate_count:
        [...new Set(duplicates)].length,

      pubmed_ids:
        uniqueIds,

      pubmed_id_string:
        uniqueIds.join(','),

      pubmed_count:
        uniqueIds.length,

      has_results:
        uniqueIds.length > 0
    }
  }
];

const job = $('Prepare EMA Job').first().json;

const articles =
  $json.PubmedArticleSet?.PubmedArticle ?? [];

function asArray(value) {
  if (value == null) return [];
  return Array.isArray(value) ? value : [value];
}

function getText(value) {
  if (value == null) return null;

  if (
    typeof value === 'string' ||
    typeof value === 'number'
  ) {
    return String(value);
  }

  if (Array.isArray(value)) {
    return value
      .map(getText)
      .filter(Boolean)
      .join(' ');
  }

  if (
    typeof value === 'object' &&
    value._ != null
  ) {
    return getText(value._);
  }

  return null;
}

function getAbstract(article) {
  const parts = asArray(
    article?.Abstract?.AbstractText
  );

  const text = parts
    .map(part => {
      if (typeof part === 'string') {
        return part;
      }

      const content = getText(part);
      const label = part?.Label ?? null;

      if (!content) return null;

      return label
        ? `${label}: ${content}`
        : content;
    })
    .filter(Boolean);

  return text.join('\n\n');
}

function getPublicationTypes(article) {
  return asArray(
    article?.PublicationTypeList?.PublicationType
  )
    .map(getText)
    .filter(Boolean);
}

function getAuthors(article) {
  return asArray(
    article?.AuthorList?.Author
  )
    .map(author => {
      const last = author?.LastName ?? '';
      const fore = author?.ForeName ?? '';
      const initials = author?.Initials ?? '';

      const name =
        [last, fore].filter(Boolean).join(', ') ||
        [last, initials].filter(Boolean).join(' ');

      return name || null;
    })
    .filter(Boolean);
}

function getArticleId(pubmedData, type) {
  const ids = asArray(
    pubmedData?.ArticleIdList?.ArticleId
  );

  const match = ids.find(
    id => id?.IdType === type
  );

  return match ? getText(match) : null;
}

function getYear(citation) {
  const article = citation?.Article ?? {};

  return (
    article?.ArticleDate?.Year ??
    article?.Journal?.JournalIssue?.PubDate?.Year ??
    citation?.DateCompleted?.Year ??
    null
  );
}

return articles.map(item => {
  const citation =
    item?.MedlineCitation ?? {};

  const article =
    citation?.Article ?? {};

  const pubmedData =
    item?.PubmedData ?? {};

  const pmid =
    getText(citation?.PMID);

  const abstract =
    getAbstract(article);

  return {
    json: {
      queue_id: job.queue_id,
      plant_id: job.plant_id,
      scientific_name: job.scientific_name,
      target_indication: job.target_indication,
      indication_context: job.indication_context,

      pmid,

      title:
        getText(article?.ArticleTitle),

      abstract:
        abstract || null,

      year:
        getYear(citation),

      journal:
        getText(
          article?.Journal?.ISOAbbreviation
        ) ??
        getText(
          article?.Journal?.Title
        ),

      publication_types:
        getPublicationTypes(article),

      authors:
        getAuthors(article),

      language:
        asArray(article?.Language)
          .map(getText)
          .filter(Boolean),

      doi:
        getArticleId(
          pubmedData,
          'doi'
        ),

      pmc_id:
        getArticleId(
          pubmedData,
          'pmc'
        ),

      pubmed_url:
        pmid
          ? `https://pubmed.ncbi.nlm.nih.gov/${pmid}/`
          : null,

      has_abstract:
        Boolean(
          abstract &&
          abstract.trim().length > 0
        ),

      abstract_characters:
        abstract?.length ?? 0
    }
  };
});

const article =
  $('Define Evidence Screening Schema').item.json;

const rawOutput = $json.text ?? '';

const errors = [];
const warnings = [];

// --------------------------------------------------
// 1. Clean model output
// --------------------------------------------------

function cleanJsonString(value) {
  return String(value ?? '')
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();
}

// --------------------------------------------------
// 2. Parse JSON
// --------------------------------------------------

let screening = null;

try {
  screening = JSON.parse(
    cleanJsonString(rawOutput)
  );
} catch (error) {
  errors.push({
    type: 'json_parse_error',
    message: error.message
  });
}

// --------------------------------------------------
// 3. Allowed values
// --------------------------------------------------

const allowedDecisions = [
  'include',
  'exclude',
  'uncertain'
];

const allowedRelations = [
  'exact_match',
  'partial_overlap',
  'related',
  'unrelated',
  'uncertain'
];

const allowedDesigns = [
  'systematic_review_meta_analysis',
  'systematic_review',
  'randomized_controlled_trial',
  'clinical_trial',
  'other'
];

const expectedKeys = [
  'screening_decision',
  'indication_relation',
  'direct_plant_match',
  'plant_specific_efficacy_evidence',
  'human_clinical_evidence',
  'evidence_design',
  'reason',
  'supporting_quote'
];

// --------------------------------------------------
// 4. Validate structure
// --------------------------------------------------

if (screening !== null) {

  const actualKeys =
    Object.keys(screening);

  for (const key of expectedKeys) {
    if (!(key in screening)) {
      errors.push({
        type: 'missing_key',
        field: key
      });
    }
  }

  for (const key of actualKeys) {
    if (!expectedKeys.includes(key)) {
      warnings.push({
        type: 'unexpected_key',
        field: key
      });
    }
  }

  if (
    !allowedDecisions.includes(
      screening.screening_decision
    )
  ) {
    errors.push({
      type: 'invalid_screening_decision',
      value: screening.screening_decision
    });
  }

  if (
    !allowedRelations.includes(
      screening.indication_relation
    )
  ) {
    errors.push({
      type: 'invalid_indication_relation',
      value: screening.indication_relation
    });
  }

  if (
    !allowedDesigns.includes(
      screening.evidence_design
    )
  ) {
    errors.push({
      type: 'invalid_evidence_design',
      value: screening.evidence_design
    });
  }

  if (
    typeof screening.direct_plant_match
      !== 'boolean'
  ) {
    errors.push({
      type: 'invalid_boolean',
      field: 'direct_plant_match'
    });
  }

  if (
    typeof screening.plant_specific_efficacy_evidence
      !== 'boolean'
  ) {
    errors.push({
      type: 'invalid_boolean',
      field: 'plant_specific_efficacy_evidence'
    });
  }

  if (
    typeof screening.human_clinical_evidence
      !== 'boolean'
  ) {
    errors.push({
      type: 'invalid_boolean',
      field: 'human_clinical_evidence'
    });
  }
}

// --------------------------------------------------
// 5. Quote grounding
// --------------------------------------------------

function normalizeText(value) {
  return String(value ?? '')
    .normalize('NFKC')
    .replace(/\u00AD/g, '')
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/[‐-‒–—−]/g, '-')
    .replace(/\u00A0/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

if (
  screening !== null &&
  typeof screening.supporting_quote
    === 'string' &&
  screening.supporting_quote.trim().length > 0
) {

  const sourceText = normalizeText(
    [
      article.title,
      article.abstract
    ]
      .filter(Boolean)
      .join('\n')
  );

  const quote =
    normalizeText(
      screening.supporting_quote
    );

  if (!sourceText.includes(quote)) {
    errors.push({
      type: 'ungrounded_supporting_quote',
      message:
        'Supporting quote could not be found in title or abstract.'
    });
  }
}

// --------------------------------------------------
// 6. Logical consistency checks
// --------------------------------------------------

if (screening !== null) {

  if (
    screening.screening_decision === 'include' &&
    screening.direct_plant_match !== true
  ) {
    errors.push({
      type: 'logic_error',
      message:
        'Included article must directly evaluate the target plant.'
    });
  }

  if (
    screening.screening_decision === 'include' &&
    screening.plant_specific_efficacy_evidence !== true
  ) {
    errors.push({
      type: 'logic_error',
      message:
        'Included article must provide plant-specific clinical efficacy evidence.'
    });
  }

  if (
    screening.screening_decision === 'include' &&
    screening.human_clinical_evidence !== true
  ) {
    errors.push({
      type: 'logic_error',
      message:
        'Included article must contain human clinical efficacy evidence.'
    });
  }

  if (
    screening.screening_decision === 'include' &&
    ![
      'exact_match',
      'partial_overlap'
    ].includes(
      screening.indication_relation
    )
  ) {
    errors.push({
      type: 'logic_error',
      message:
        'Included article must have exact_match or partial_overlap indication relation.'
    });
  }

  if (
    screening.screening_decision === 'exclude' &&
    screening.direct_plant_match === true &&
    screening.plant_specific_efficacy_evidence === true &&
    screening.human_clinical_evidence === true &&
    [
      'exact_match',
      'partial_overlap'
    ].includes(
      screening.indication_relation
    )
  ) {
    warnings.push({
      type: 'possible_over_exclusion',
      message:
        'Article appears to meet all inclusion criteria but was excluded.'
    });
  }
}

// --------------------------------------------------
// 7. Overall validation status
// --------------------------------------------------

let validationStatus = 'pass';

if (errors.length > 0) {
  validationStatus = 'fail';
} else if (warnings.length > 0) {
  validationStatus = 'warning';
}

// --------------------------------------------------
// 8. Return article + screening result
// --------------------------------------------------

return {
  json: {
    queue_id: article.queue_id,
    plant_id: article.plant_id,
    scientific_name:
      article.scientific_name,

    target_indication:
      article.target_indication,

    indication_context:
      article.indication_context,

    pmid:
      article.pmid,

    title:
      article.title,

    abstract:
      article.abstract,

    year:
      article.year,

    journal:
      article.journal,

    publication_types:
      article.publication_types,

    authors:
      article.authors,

    doi:
      article.doi,

    pubmed_url:
      article.pubmed_url,

    screening:
      screening,

    validation: {
      status: validationStatus,
      error_count: errors.length,
      warning_count: warnings.length,
      errors,
      warnings
    },

    screening_schema_version:
      'phythera_pubmed_screen_v3'
  }
};

const article =
  $('Define Outcome Extraction Schema').item.json;

const rawOutput = $json.text ?? '';

const errors = [];
const warnings = [];

// --------------------------------------------------
// 1. Clean model output
// --------------------------------------------------

function cleanJsonString(value) {
  return String(value ?? '')
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();
}

// --------------------------------------------------
// 2. Parse JSON
// --------------------------------------------------

let extraction = null;

try {
  extraction = JSON.parse(
    cleanJsonString(rawOutput)
  );
} catch (error) {
  errors.push({
    type: 'json_parse_error',
    message: error.message
  });
}

// --------------------------------------------------
// 3. Allowed values
// --------------------------------------------------

const allowedPublicationRoles = [
  'primary_trial_report',
  'continuation_follow_up_report',
  'systematic_review_meta_analysis',
  'systematic_review',
  'other'
];

const allowedStudyPhases = [
  'acute_treatment',
  'continuation',
  'maintenance',
  'follow_up',
  'review_level',
  'unclear'
];

const allowedOutcomeDirections = [
  'supportive',
  'not_supportive',
  'mixed',
  'unclear'
];

const expectedKeys = [
  'publication_role',
  'study_phase',

  'population',
  'sample_size',
  'indication_as_studied',

  'intervention',
  'preparation_or_extract',
  'dose_regimen',

  'comparator',
  'treatment_duration',

  'primary_efficacy_outcome',
  'effect_estimate',

  'outcome_direction',
  'efficacy_summary',

  'parent_trial_reference',

  'supporting_quote'
];

// --------------------------------------------------
// 4. Structure validation
// --------------------------------------------------

if (extraction !== null) {

  const actualKeys =
    Object.keys(extraction);

  for (const key of expectedKeys) {
    if (!(key in extraction)) {
      errors.push({
        type: 'missing_key',
        field: key
      });
    }
  }

  for (const key of actualKeys) {
    if (!expectedKeys.includes(key)) {
      warnings.push({
        type: 'unexpected_key',
        field: key
      });
    }
  }

  if (
    !allowedPublicationRoles.includes(
      extraction.publication_role
    )
  ) {
    errors.push({
      type: 'invalid_publication_role',
      value: extraction.publication_role
    });
  }

  if (
    !allowedStudyPhases.includes(
      extraction.study_phase
    )
  ) {
    errors.push({
      type: 'invalid_study_phase',
      value: extraction.study_phase
    });
  }

  if (
    !allowedOutcomeDirections.includes(
      extraction.outcome_direction
    )
  ) {
    errors.push({
      type: 'invalid_outcome_direction',
      value: extraction.outcome_direction
    });
  }

  if (
    extraction.sample_size !== null &&
    (
      typeof extraction.sample_size !== 'number' ||
      !Number.isFinite(extraction.sample_size) ||
      extraction.sample_size <= 0
    )
  ) {
    errors.push({
      type: 'invalid_sample_size',
      value: extraction.sample_size
    });
  }
}

// --------------------------------------------------
// 5. Text normalization for quote grounding
// --------------------------------------------------

function normalizeText(value) {
  return String(value ?? '')
    .normalize('NFKC')
    .replace(/\u00AD/g, '')
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/[‐-‒–—−]/g, '-')
    .replace(/\u00A0/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

// --------------------------------------------------
// 6. Validate supporting quote
// --------------------------------------------------

if (
  extraction !== null &&
  typeof extraction.supporting_quote === 'string' &&
  extraction.supporting_quote.trim().length > 0
) {

  const sourceText =
    normalizeText(
      [
        article.title,
        article.abstract
      ]
        .filter(Boolean)
        .join('\n')
    );

  const quote =
    normalizeText(
      extraction.supporting_quote
    );

  if (!sourceText.includes(quote)) {
    errors.push({
      type: 'ungrounded_supporting_quote',
      message:
        'Supporting quote could not be found in title or abstract.'
    });
  }
}

// --------------------------------------------------
// 7. Logical consistency
// --------------------------------------------------

if (extraction !== null) {

  const reviewRoles = [
    'systematic_review_meta_analysis',
    'systematic_review'
  ];

  const continuationPhases = [
    'continuation',
    'maintenance',
    'follow_up'
  ];

  // Reviews should be review-level
  if (
    reviewRoles.includes(
      extraction.publication_role
    ) &&
    extraction.study_phase !== 'review_level'
  ) {
    errors.push({
      type: 'logic_error',
      message:
        'Systematic reviews must use study_phase = review_level.'
    });
  }

  // Review-level phase should belong to a review
  if (
    extraction.study_phase === 'review_level' &&
    !reviewRoles.includes(
      extraction.publication_role
    )
  ) {
    errors.push({
      type: 'logic_error',
      message:
        'study_phase = review_level requires a systematic review publication role.'
    });
  }

  // Continuation publications need an appropriate phase
  if (
    extraction.publication_role ===
      'continuation_follow_up_report' &&
    !continuationPhases.includes(
      extraction.study_phase
    )
  ) {
    errors.push({
      type: 'logic_error',
      message:
        'Continuation/follow-up publications must use continuation, maintenance, or follow_up study phase.'
    });
  }

  // Parent reference should normally only appear for continuation reports
  if (
    extraction.parent_trial_reference !== null &&
    extraction.publication_role !==
      'continuation_follow_up_report'
  ) {
    warnings.push({
      type: 'unexpected_parent_trial_reference',
      message:
        'Parent trial reference is present for a publication not classified as continuation/follow-up.'
    });
  }

  // Continuation publication without identifiable parent context
  if (
    extraction.publication_role ===
      'continuation_follow_up_report' &&
    extraction.parent_trial_reference === null
  ) {
    warnings.push({
      type: 'missing_parent_trial_reference',
      message:
        'Continuation/follow-up publication has no parent trial reference in the abstract.'
    });
  }

  // Efficacy summary should be present
  if (
    typeof extraction.efficacy_summary !== 'string' ||
    extraction.efficacy_summary.trim().length === 0
  ) {
    errors.push({
      type: 'missing_efficacy_summary'
    });
  }
}

// --------------------------------------------------
// 8. Validation status
// --------------------------------------------------

let validationStatus = 'pass';

if (errors.length > 0) {
  validationStatus = 'fail';
} else if (warnings.length > 0) {
  validationStatus = 'warning';
}

// --------------------------------------------------
// 9. Return article + extraction
// --------------------------------------------------

return {
  json: {
    queue_id:
      article.queue_id,

    plant_id:
      article.plant_id,

    scientific_name:
      article.scientific_name,

    target_indication:
      article.target_indication,

    indication_context:
      article.indication_context,

    pmid:
      article.pmid,

    title:
      article.title,

    year:
      article.year,

    journal:
      article.journal,

    doi:
      article.doi,

    pubmed_url:
      article.pubmed_url,

    screening:
      article.screening,

    outcome_extraction:
      extraction,

    validation: {
      status:
        validationStatus,

      error_count:
        errors.length,

      warning_count:
        warnings.length,

      errors,
      warnings
    },

    outcome_schema_version:
      'phythera_pubmed_outcome_v3'
  }
};

const items = $input.all();

function norm(value) {
  return String(value ?? '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

function hasTerm(value, term) {
  return norm(value).includes(norm(term));
}

function getCochraneFamily(doi) {
  if (!doi) return null;

  const match =
    String(doi).match(/CD\d+/i);

  if (!match) return null;

  return `review:cochrane:${match[0].toUpperCase()}`;
}

// --------------------------------------------------
// 1. Find primary clinical trial reports
// --------------------------------------------------

const primaryTrials = items.filter(item =>
  item.json.outcome_extraction?.publication_role ===
  'primary_trial_report'
);

// --------------------------------------------------
// 2. Process each evidence record
// --------------------------------------------------

return items.map(item => {
  const record = item.json;
  const outcome =
    record.outcome_extraction ?? {};

  const role =
    outcome.publication_role;

  let evidence_family_type = null;
  let evidence_family_id = null;
  let publication_relationship = null;
  let score_eligible = true;
  let score_exclusion_reason = null;
  let linked_parent_pmid = null;

  // ==================================================
  // REVIEWS
  // ==================================================

  if (
    role === 'systematic_review' ||
    role === 'systematic_review_meta_analysis'
  ) {
    evidence_family_type = 'review';

    const cochraneFamily =
      getCochraneFamily(record.doi);

    if (cochraneFamily) {
      evidence_family_id =
        cochraneFamily;

      publication_relationship =
        'review_family_member';
    } else {
      evidence_family_id =
        `review:pmid:${record.pmid}`;

      publication_relationship =
        'independent_review';
    }
  }

  // ==================================================
  // PRIMARY TRIAL
  // ==================================================

  else if (
    role === 'primary_trial_report'
  ) {
    evidence_family_type = 'trial';

    evidence_family_id =
      `trial:pmid:${record.pmid}`;

    publication_relationship =
      'primary';
  }

  // ==================================================
  // CONTINUATION / FOLLOW-UP
  // ==================================================

  else if (
    role ===
    'continuation_follow_up_report'
  ) {
    evidence_family_type = 'trial';

    const preparation =
      norm(outcome.preparation_or_extract);

    const comparator =
      norm(outcome.comparator);

    const indication =
      norm(outcome.indication_as_studied);

    // Find possible parent trial
    const candidates =
      primaryTrials.filter(candidate => {
        const c =
          candidate.json.outcome_extraction ?? {};

        const samePreparation =
          preparation &&
          norm(c.preparation_or_extract) ===
            preparation;

        const candidateComparator =
          norm(c.comparator);

        const comparatorOverlap =
          comparator &&
          candidateComparator &&
          (
            (
              hasTerm(comparator, 'placebo') &&
              hasTerm(candidateComparator, 'placebo')
            )
            ||
            (
              hasTerm(comparator, 'sertraline') &&
              hasTerm(candidateComparator, 'sertraline')
            )
          );

        const candidateIndication =
          norm(c.indication_as_studied);

        const indicationOverlap =
          indication &&
          candidateIndication &&
          (
            indication.includes(candidateIndication) ||
            candidateIndication.includes(indication) ||
            (
              indication.includes('major depress') &&
              candidateIndication.includes('major depress')
            )
          );

        return (
          samePreparation &&
          comparatorOverlap &&
          indicationOverlap
        );
      });

    // Exactly one plausible parent
    if (candidates.length === 1) {
      const parent =
        candidates[0].json;

      linked_parent_pmid =
        parent.pmid;

      evidence_family_id =
        `trial:pmid:${parent.pmid}`;

      publication_relationship =
        'continuation_of_primary';

      // Do not count publication twice
      score_eligible = false;

      score_exclusion_reason =
        'continuation_publication_parent_present';
    }

    // No parent in current retrieval
    else {
      evidence_family_id =
        `trial:pmid:${record.pmid}`;

      publication_relationship =
        'continuation_parent_not_retrieved';

      // Keep eligible for now because otherwise
      // the entire clinical evidence family would disappear.
      score_eligible = true;
    }
  }

  // ==================================================
  // OTHER
  // ==================================================

  else {
    evidence_family_type =
      'other';

    evidence_family_id =
      `other:pmid:${record.pmid}`;

    publication_relationship =
      'independent';
  }

  return {
    json: {
      ...record,

      evidence_family: {
        family_type:
          evidence_family_type,

        family_id:
          evidence_family_id,

        publication_relationship,

        linked_parent_pmid,

        score_eligible,

        score_exclusion_reason
      },

      evidence_family_schema_version:
        'phythera_evidence_family_v1'
    }
  };
});

const items = $input.all();

// Group records by evidence family
const families = new Map();

for (const item of items) {
  const familyId =
    item.json.evidence_family?.family_id ??
    `fallback:${item.json.pmid}`;

  if (!families.has(familyId)) {
    families.set(familyId, []);
  }

  families.get(familyId).push(item);
}

function yearValue(item) {
  const year = Number(item.json.year);
  return Number.isFinite(year) ? year : 0;
}

function rolePriority(item) {
  const role =
    item.json.outcome_extraction?.publication_role;

  if (role === 'primary_trial_report') {
    return 4;
  }

  if (
    role ===
    'systematic_review_meta_analysis'
  ) {
    return 3;
  }

  if (role === 'systematic_review') {
    return 2;
  }

  if (
    role ===
    'continuation_follow_up_report'
  ) {
    return 1;
  }

  return 0;
}

const result = [];

for (const [familyId, members] of families.entries()) {

  const familyType =
    members[0].json.evidence_family?.family_type;

  let representative;

  // -----------------------------------------
  // TRIAL FAMILY
  // Prefer primary publication.
  // If unavailable, use newest continuation.
  // -----------------------------------------

  if (familyType === 'trial') {

    const primary =
      members.find(
        item =>
          item.json.outcome_extraction
            ?.publication_role ===
          'primary_trial_report'
      );

    if (primary) {
      representative = primary;
    } else {
      representative =
        [...members].sort(
          (a, b) =>
            yearValue(b) -
            yearValue(a)
        )[0];
    }
  }

  // -----------------------------------------
  // REVIEW FAMILY
  // Prefer newest update.
  // If same year, prefer meta-analysis.
  // -----------------------------------------

  else if (familyType === 'review') {

    representative =
      [...members].sort((a, b) => {

        const yearDifference =
          yearValue(b) -
          yearValue(a);

        if (yearDifference !== 0) {
          return yearDifference;
        }

        return (
          rolePriority(b) -
          rolePriority(a)
        );
      })[0];
  }

  // -----------------------------------------
  // OTHER
  // -----------------------------------------

  else {
    representative =
      [...members].sort(
        (a, b) =>
          yearValue(b) -
          yearValue(a)
      )[0];
  }

  // -----------------------------------------
  // Annotate every publication
  // -----------------------------------------

  for (const item of members) {

    const isRepresentative =
      item === representative;

    const existing =
      item.json.evidence_family ?? {};

    let scoreEligible =
      existing.score_eligible === true &&
      isRepresentative;

    let exclusionReason =
      existing.score_exclusion_reason;

    if (
      !isRepresentative &&
      !exclusionReason
    ) {
      exclusionReason =
        'non_representative_family_publication';
    }

    result.push({
      json: {
        ...item.json,

        evidence_family: {
          ...existing,

          family_representative:
            isRepresentative,

          score_eligible:
            scoreEligible,

          score_exclusion_reason:
            scoreEligible
              ? null
              : exclusionReason
        },

        evidence_family_selection_version:
          'phythera_family_selection_v1'
      }
    });
  }
}

return result;

const items = $input.all();

// --------------------------------------------------
// CONFIGURATION
// --------------------------------------------------

// Direction of clinical efficacy evidence.
// This is NOT an efficacy probability.
const directionScores = {
  supportive: 1.0,
  mixed: 0.5,
  not_supportive: 0.0,
  unclear: null
};

// How closely the investigated indication
// matches the PhyThera target indication.
const indicationWeights = {
  exact_match: 1.0,
  partial_overlap: 0.85,
  related: 0.50,
  unrelated: 0.0
};

// Relative weights WITHIN the review layer.
const reviewWeights = {
  systematic_review_meta_analysis: 1.0,
  systematic_review: 0.9
};

// Relative weights WITHIN the trial layer.
//
// A continuation publication whose parent trial
// is not available is retained, but receives
// less weight than a primary trial report.
const trialWeights = {
  primary_trial_report: 1.0,
  continuation_follow_up_report: 0.7
};

// Fixed combination of evidence layers.
//
// Reviews are weighted slightly more strongly
// because they synthesize multiple clinical trials.
//
// Importantly, publication COUNT does not determine
// the review-vs-trial balance.
const REVIEW_LAYER_WEIGHT = 0.60;
const TRIAL_LAYER_WEIGHT = 0.40;


// --------------------------------------------------
// HELPERS
// --------------------------------------------------

function weightedMean(records) {
  if (!records.length) {
    return null;
  }

  let numerator = 0;
  let denominator = 0;

  for (const record of records) {
    numerator +=
      record.family_score *
      record.evidence_weight;

    denominator +=
      record.evidence_weight;
  }

  if (denominator === 0) {
    return null;
  }

  return numerator / denominator;
}

function round(value, digits = 3) {
  if (value === null || value === undefined) {
    return null;
  }

  const factor = 10 ** digits;

  return (
    Math.round(value * factor) /
    factor
  );
}


// --------------------------------------------------
// SELECT SCORE-ELIGIBLE FAMILY REPRESENTATIVES
// --------------------------------------------------

const eligible = items.filter(item => {

  const record = item.json;

  return (
    record.validation?.status === 'pass' &&
    record.evidence_family
      ?.family_representative === true &&
    record.evidence_family
      ?.score_eligible === true
  );
});


// --------------------------------------------------
// CALCULATE FAMILY-LEVEL CONTRIBUTIONS
// --------------------------------------------------

const familyContributions = [];

for (const item of eligible) {

  const record = item.json;

  const family =
    record.evidence_family ?? {};

  const outcome =
    record.outcome_extraction ?? {};

  const screening =
    record.screening ?? {};

  const direction =
    outcome.outcome_direction;

  const relation =
    screening.indication_relation;

  const directionScore =
    directionScores[direction];

  const indicationWeight =
    indicationWeights[relation] ?? 0;

  // Ignore unclear efficacy direction
  // rather than treating it as negative evidence.
  if (
    directionScore === null ||
    directionScore === undefined
  ) {
    continue;
  }

  const familyScore =
    directionScore *
    indicationWeight;

  let evidenceWeight = 1.0;

  if (family.family_type === 'review') {

    evidenceWeight =
      reviewWeights[
        screening.evidence_design
      ] ?? 0.8;

  } else if (
    family.family_type === 'trial'
  ) {

    evidenceWeight =
      trialWeights[
        outcome.publication_role
      ] ?? 0.7;
  }

  familyContributions.push({
    pmid:
      record.pmid,

    family_id:
      family.family_id,

    family_type:
      family.family_type,

    publication_role:
      outcome.publication_role,

    evidence_design:
      screening.evidence_design,

    indication_relation:
      relation,

    outcome_direction:
      direction,

    direction_score:
      directionScore,

    indication_weight:
      indicationWeight,

    evidence_weight:
      evidenceWeight,

    family_score:
      round(familyScore)
  });
}


// --------------------------------------------------
// SPLIT INTO REVIEW AND TRIAL LAYERS
// --------------------------------------------------

const reviewFamilies =
  familyContributions.filter(
    record =>
      record.family_type === 'review'
  );

const trialFamilies =
  familyContributions.filter(
    record =>
      record.family_type === 'trial'
  );

const reviewScore =
  weightedMean(reviewFamilies);

const trialScore =
  weightedMean(trialFamilies);


// --------------------------------------------------
// COMBINE LAYERS
// --------------------------------------------------

let modernEvidenceScore = null;
let appliedReviewWeight = 0;
let appliedTrialWeight = 0;

if (
  reviewScore !== null &&
  trialScore !== null
) {

  modernEvidenceScore =
    reviewScore *
      REVIEW_LAYER_WEIGHT +
    trialScore *
      TRIAL_LAYER_WEIGHT;

  appliedReviewWeight =
    REVIEW_LAYER_WEIGHT;

  appliedTrialWeight =
    TRIAL_LAYER_WEIGHT;

} else if (reviewScore !== null) {

  modernEvidenceScore =
    reviewScore;

  appliedReviewWeight = 1.0;

} else if (trialScore !== null) {

  modernEvidenceScore =
    trialScore;

  appliedTrialWeight = 1.0;
}


// --------------------------------------------------
// SUMMARY COUNTS
// --------------------------------------------------

const excludedPublications =
  items.filter(
    item =>
      item.json.evidence_family
        ?.score_eligible !== true
  );

const supportiveCount =
  familyContributions.filter(
    x =>
      x.outcome_direction ===
      'supportive'
  ).length;

const mixedCount =
  familyContributions.filter(
    x =>
      x.outcome_direction ===
      'mixed'
  ).length;

const notSupportiveCount =
  familyContributions.filter(
    x =>
      x.outcome_direction ===
      'not_supportive'
  ).length;


// --------------------------------------------------
// OUTPUT ONE MODERN-EVIDENCE PROFILE
// --------------------------------------------------

const first =
  items[0]?.json ?? {};

const indication =
  $('Lookup PubMed Indication')
    .first()
    .json;

return [
  {
    json: {
      queue_id:
        first.queue_id,

      plant_id:
        first.plant_id,

      indication_id:
        indication.id,

      scientific_name:
        first.scientific_name,

      target_indication:
        first.target_indication,

      indication_context:
        first.indication_context,

      modern_evidence: {

        score:
          round(modernEvidenceScore),

        score_100:
          modernEvidenceScore === null
            ? null
            : round(
                modernEvidenceScore * 100,
                1
              ),

        review_layer_score:
          round(reviewScore),

        trial_layer_score:
          round(trialScore),

        review_layer_weight:
          appliedReviewWeight,

        trial_layer_weight:
          appliedTrialWeight,

        eligible_family_count:
          familyContributions.length,

        review_family_count:
          reviewFamilies.length,

        trial_family_count:
          trialFamilies.length,

        supportive_family_count:
          supportiveCount,

        mixed_family_count:
          mixedCount,

        not_supportive_family_count:
          notSupportiveCount,

        excluded_publication_count:
          excludedPublications.length,

        family_contributions:
          familyContributions
      },

      modern_evidence_score_version:
        'phythera_modern_evidence_v2'
    }
  }
];

// ============================================================
// Prepare Modern Evidence DB Update
//
// Input:
//   Calculate Modern Evidence Score
//
// Purpose:
//   Prepare the deterministic Modern Evidence Score
//   for writing back to Supabase:
//
//   plant_indication_profiles.modern_evidence_score
//
// IMPORTANT:
//   Database score scale = 0–1
//   UI can display score × 100
// ============================================================

const items = $input.all();

const output = [];

for (const item of items) {
  const data = item.json;

  const plantId = data.plant_id;
  const indicationId = data.indication_id;

  const modernEvidenceScore =
    data.modern_evidence?.score ?? null;

  const modernEvidenceScore100 =
    data.modern_evidence?.score_100 ?? null;


  // ==========================================================
  // Validation
  // ==========================================================

  if (!plantId) {
    throw new Error(
      "Prepare Modern Evidence DB Update: plant_id is missing."
    );
  }

  if (!indicationId) {
    throw new Error(
      "Prepare Modern Evidence DB Update: indication_id is missing."
    );
  }

  if (
    modernEvidenceScore !== null &&
    (
      typeof modernEvidenceScore !== "number" ||
      Number.isNaN(modernEvidenceScore) ||
      modernEvidenceScore < 0 ||
      modernEvidenceScore > 1
    )
  ) {
    throw new Error(
      `Invalid modern_evidence.score for plant_id ${plantId}, indication_id ${indicationId}: ${modernEvidenceScore}`
    );
  }


  // ==========================================================
  // Output
  // ==========================================================

  output.push({
    json: {

      // --------------------------------------------------------
      // Keys for identifying plant_indication_profiles row
      // --------------------------------------------------------

      plant_id: plantId,
      indication_id: indicationId,


      // --------------------------------------------------------
      // Main DB value
      // --------------------------------------------------------

      modern_evidence_score:
        modernEvidenceScore,


      // --------------------------------------------------------
      // Keep useful workflow context
      // --------------------------------------------------------

      queue_id:
        data.queue_id ?? null,

      scientific_name:
        data.scientific_name ?? null,

      target_indication:
        data.target_indication ?? null,

      indication_context:
        data.indication_context ?? null,


      // --------------------------------------------------------
      // Diagnostic / audit information
      // Not required for plant_indication_profiles update,
      // but kept for downstream workflow nodes.
      // --------------------------------------------------------

      modern_evidence_score_100:
        modernEvidenceScore100,

      modern_evidence_score_version:
        data.modern_evidence_score_version ??
        "phythera_modern_evidence_v2",

      modern_evidence:
        data.modern_evidence ?? null
    }
  });
}

return output;

// ============================================================
// Calculate Traditional Support Score
// Version: phythera_traditional_support_v2
//
// EMA/HMPC regulatory / traditional support:
//
// Well-established use  -> 1.00
// Traditional use       -> 0.75
// Documented medicinal use only -> 0.50
// No documented support -> 0.00
//
// Missing / unusable EMA extraction -> null
// ============================================================

const items = $input.all();


// ============================================================
// Helpers
// ============================================================

function parseProfile(value) {

  if (!value) {
    return {};
  }

  if (typeof value === 'object') {
    return value;
  }

  if (typeof value === 'string') {

    try {
      return JSON.parse(value);
    } catch {
      return {};
    }
  }

  return {};
}


function normalize(value) {

  if (
    value === null ||
    value === undefined
  ) {
    return '';
  }

  return String(value)
    .trim()
    .toLowerCase();
}


// ============================================================
// Detect explicitly negative statements
// ============================================================

function isNegativeStatement(value) {

  const text =
    normalize(value);

  if (!text) {
    return false;
  }

  const negativePatterns = [

    'not supported',
    'not established',
    'not fulfilled',
    'requirements not fulfilled',

    'insufficient',
    'unsupported',

    'no evidence',
    'no clinical evidence',
    'no clinical data',

    'does not support',
    'cannot support',

    'not acceptable',

    'no well-established',
    'well-established use is not supported'
  ];

  return negativePatterns.some(
    pattern =>
      text.includes(pattern)
  );
}


// ============================================================
// Traditional-use signal
// ============================================================

function isTraditionalUseSignal(value) {

  const text =
    normalize(value);

  if (!text) {
    return false;
  }

  if (isNegativeStatement(text)) {
    return false;
  }

  return (
    text === 'traditional' ||
    text === 'traditional use' ||

    text.includes(
      'traditional use'
    ) ||

    text.includes(
      'traditional medicinal'
    ) ||

    (
      text.includes('traditional') &&
      text.includes('fulfilled')
    )
  );
}


// ============================================================
// Well-established-use signal
// ============================================================

function isWellEstablishedSignal(value) {

  const text =
    normalize(value);

  if (!text) {
    return false;
  }

  if (isNegativeStatement(text)) {
    return false;
  }

  return (
    text === 'well-established' ||
    text === 'well established' ||

    text.includes(
      'well-established use'
    ) ||

    text.includes(
      'well established use'
    ) ||

    (
      (
        text.includes('well-established') ||
        text.includes('well established')
      ) &&
      text.includes('fulfilled')
    )
  );
}


// ============================================================
// Collect EMA extraction runs
// ============================================================

const runs = items
  .map(item => {

    const row =
      item.json;

    const profile =
      parseProfile(
        row.profile_json
      );

    return {
      row,
      profile
    };
  })

  .filter(({ row }) =>
    row.pipeline ===
      'PhyThera EMA Extraction'
  )

  .sort((a, b) => {

    const dateA =
      new Date(
        a.row.created_at ?? 0
      );

    const dateB =
      new Date(
        b.row.created_at ?? 0
      );

    return dateB - dateA;
  });


// ============================================================
// Find newest usable EMA extraction
// ============================================================

let selected = null;

for (const run of runs) {

  const validationStatus =
    normalize(
      run.row.validation_status
    );

  if (
    validationStatus !== 'pass' &&
    validationStatus !== 'warning'
  ) {
    continue;
  }


  const medicinalUseTaskStatus =
    normalize(
      run.profile
        ?.validation_summary
        ?.task_status
        ?.medicinal_use
    );


  // Overall extraction may contain a warning from another task.
  // Medicinal-use extraction itself must not have failed.
  if (
    medicinalUseTaskStatus &&
    medicinalUseTaskStatus !== 'pass' &&
    medicinalUseTaskStatus !== 'warning'
  ) {
    continue;
  }


  selected = run;
  break;
}


// ============================================================
// No usable EMA extraction
// ============================================================

if (!selected) {

  const fallback =
    runs[0]?.row ?? {};

  return [
    {
      json: {

        plant_id:
          fallback.plant_id ?? null,

        indication_id:
          fallback.indication_id ?? null,

        traditional_support_score:
          null,

        traditional_support_level:
          'unavailable',

        traditional_support_basis:
          'No usable EMA medicinal-use extraction was available.',

        traditional_support_reason:
          'No usable EMA medicinal-use extraction was available.',

        ema_extraction_run_id:
          fallback.id ?? null,

        ema_validation_status:
          fallback.validation_status ?? null,

        traditional_support_score_version:
          'phythera_traditional_support_v2'
      }
    }
  ];
}


// ============================================================
// Extract profile sections
// ============================================================

const row =
  selected.row;

const profile =
  selected.profile;

const medicinalUse =
  profile?.medicinal_use ?? {};

const clinicalEfficacy =
  profile?.clinical_efficacy ?? {};

const overallAssessment =
  profile?.overall_assessment ?? {};

const constituents =
  profile?.constituents ?? {};


// ============================================================
// Indications
// ============================================================

const indications =
  Array.isArray(
    medicinalUse?.indications
  )
    ? medicinalUse.indications
    : [];


// ============================================================
// WELL-ESTABLISHED signals
// ============================================================

const wellEstablishedSignals = [

  medicinalUse
    ?.well_established_use_status,

  overallAssessment
    ?.clinical_evidence_strength
    ?.assessment,

  overallAssessment
    ?.regulatory_conclusion,

  constituents
    ?.therapeutic_activity_status
    ?.status

];


const hasWellEstablishedUse =
  clinicalEfficacy
    ?.well_established_use_supported === true ||

  wellEstablishedSignals.some(
    isWellEstablishedSignal
  );


// ============================================================
// TRADITIONAL-USE signals
//
// Important:
// EMA extraction may return:
//
// "traditional"
// "traditional use"
// "traditional medicinal product"
// regulatory_basis = "traditional use"
// "traditional use requirements fulfilled"
//
// All must count as traditional use.
// ============================================================

const traditionalSignals = [

  medicinalUse
    ?.traditional_use_status,

  ...indications.map(
    indication =>
      indication?.regulatory_basis
  ),

  overallAssessment
    ?.regulatory_conclusion

];


const hasTraditionalUse =
  traditionalSignals.some(
    isTraditionalUseSignal
  );


// ============================================================
// Score
// ============================================================

let score = 0;

let level =
  'none';

let basis =
  'No documented traditional or regulatory support for the target indication.';


// ------------------------------------------------------------
// 1. Well-established use
// ------------------------------------------------------------

if (hasWellEstablishedUse) {

  score = 1.00;

  level =
    'well_established_use';

  basis =
    'EMA documentation supports well-established medicinal use for the target indication.';
}


// ------------------------------------------------------------
// 2. Traditional use
// ------------------------------------------------------------

else if (hasTraditionalUse) {

  score = 0.75;

  level =
    'traditional_use';

  basis =
    'EMA documentation supports traditional medicinal use for the target indication.';
}


// ------------------------------------------------------------
// 3. Medicinal use documented, but no explicit TU/WEU status
// ------------------------------------------------------------

else if (
  indications.length > 0
) {

  score = 0.50;

  level =
    'documented_medicinal_use';

  basis =
    'EMA documents medicinal use, but no explicit well-established or traditional-use status was identified.';
}


// ============================================================
// Output
// ============================================================

return [
  {
    json: {

      plant_id:
        row.plant_id,

      indication_id:
        row.indication_id,

      traditional_support_score:
        score,

      traditional_support_level:
        level,

      traditional_support_basis:
        basis,

      traditional_support_reason:
        basis,

      ema_extraction_run_id:
        row.id,

      ema_validation_status:
        row.validation_status,


      // --------------------------------------------------------
      // Diagnostic information
      // --------------------------------------------------------

      traditional_use_status:
        medicinalUse
          ?.traditional_use_status ??
        null,

      well_established_use_status:
        medicinalUse
          ?.well_established_use_status ??
        null,

      well_established_use_supported:
        clinicalEfficacy
          ?.well_established_use_supported ??
        null,

      regulatory_conclusion:
        overallAssessment
          ?.regulatory_conclusion ??
        null,

      regulatory_evidence_strength:
        overallAssessment
          ?.clinical_evidence_strength
          ?.assessment ??
        null,

      therapeutic_activity_status:
        constituents
          ?.therapeutic_activity_status
          ?.status ??
        null,

      indication_regulatory_bases:
        indications
          .map(
            indication =>
              indication
                ?.regulatory_basis
          )
          .filter(Boolean),

      traditional_support_score_version:
        'phythera_traditional_support_v2'
    }
  }
];

// ============================================================
// Calculate Evidence Relevance Score
// Version: phythera_evidence_relevance_v2
//
// Base weights:
//   Modern Evidence       70%
//   Traditional Support   30%
//
// IMPORTANT:
// Missing data are NOT interpreted as zero.
// Weights are renormalized across available components.
//
// Examples:
// Modern 0.80 + Traditional 0.75
// -> 0.70*0.80 + 0.30*0.75 = 0.785
//
// Modern 0.80 + Traditional missing
// -> 0.80
// -> status = partial
//
// Modern missing + Traditional 0.75
// -> 0.75
// -> status = partial
// ============================================================

const items = $input.all();


// ============================================================
// Helper
// ============================================================

function validScore(value) {

  return (
    typeof value === 'number' &&
    Number.isFinite(value) &&
    value >= 0 &&
    value <= 1
  );
}


function round3(value) {

  return Math.round(
    (value + Number.EPSILON) * 1000
  ) / 1000;
}


// ============================================================
// Score each profile
// ============================================================

return items.map(item => {

  const data =
    item.json;


  const modernEvidence =
    data.modern_evidence_score ?? null;

  const traditionalSupport =
    data.traditional_support_score ?? null;


  const modernValid =
    validScore(modernEvidence);

  const traditionalValid =
    validScore(traditionalSupport);


  // ==========================================================
  // Base weights
  // ==========================================================

  const modernBaseWeight =
    0.70;

  const traditionalBaseWeight =
    0.30;


  // ==========================================================
  // Determine available weight
  // ==========================================================

  let availableWeight = 0;

  if (modernValid) {
    availableWeight +=
      modernBaseWeight;
  }

  if (traditionalValid) {
    availableWeight +=
      traditionalBaseWeight;
  }


  // ==========================================================
  // Calculate score
  // ==========================================================

  let evidenceRelevanceScore =
    null;

  let scoreStatus =
    'unavailable';

  let modernEffectiveWeight =
    null;

  let traditionalEffectiveWeight =
    null;


  if (availableWeight > 0) {

    let weightedSum = 0;


    // --------------------------------------------------------
    // Modern evidence
    // --------------------------------------------------------

    if (modernValid) {

      modernEffectiveWeight =
        modernBaseWeight /
        availableWeight;

      weightedSum +=
        modernEvidence *
        modernEffectiveWeight;
    }


    // --------------------------------------------------------
    // Traditional support
    // --------------------------------------------------------

    if (traditionalValid) {

      traditionalEffectiveWeight =
        traditionalBaseWeight /
        availableWeight;

      weightedSum +=
        traditionalSupport *
        traditionalEffectiveWeight;
    }


    evidenceRelevanceScore =
      round3(weightedSum);


    // --------------------------------------------------------
    // Coverage status
    // --------------------------------------------------------

    if (
      modernValid &&
      traditionalValid
    ) {

      scoreStatus =
        'complete';

    } else {

      scoreStatus =
        'partial';
    }
  }


  // ==========================================================
  // Missing-component diagnostics
  // ==========================================================

  const missingComponents = [];

  if (!modernValid) {
    missingComponents.push(
      'modern_evidence'
    );
  }

  if (!traditionalValid) {
    missingComponents.push(
      'traditional_support'
    );
  }


  // ==========================================================
  // Output
  // ==========================================================

  return {

    json: {

      ...data,


      evidence_relevance_score:
        evidenceRelevanceScore,


      evidence_relevance_score_100:
        evidenceRelevanceScore === null
          ? null
          : Math.round(
              evidenceRelevanceScore *
              1000
            ) / 10,


      evidence_relevance_status:
        scoreStatus,


      evidence_relevance_missing_components:
        missingComponents,


      evidence_relevance_components: {

        modern_evidence_score:
          modernEvidence,

        modern_evidence_available:
          modernValid,

        modern_evidence_base_weight:
          modernBaseWeight,

        modern_evidence_effective_weight:
          modernEffectiveWeight,


        traditional_support_score:
          traditionalSupport,

        traditional_support_available:
          traditionalValid,

        traditional_support_base_weight:
          traditionalBaseWeight,

        traditional_support_effective_weight:
          traditionalEffectiveWeight
      },


      evidence_relevance_score_version:
        'phythera_evidence_relevance_v2'
    }
  };
});

// ============================================================
// Classify Evidence Category
// Version: phythera_evidence_category_v2
//
// IMPORTANT:
// Missing EMA / traditional support does NOT prevent
// classification when modern evidence is available.
//
// Missing data are not interpreted as zero.
// ============================================================

const items = $input.all();


// ============================================================
// Helper
// ============================================================

function toScore(value) {

  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const n = Number(value);

  if (
    !Number.isFinite(n) ||
    n < 0 ||
    n > 1
  ) {
    return null;
  }

  return n;
}


// ============================================================
// Classification
// ============================================================

return items.map(item => {

  const data =
    item.json;


  const modern =
    toScore(
      data.modern_evidence_score
    );

  const traditional =
    toScore(
      data.traditional_support_score
    );

  const relevance =
    toScore(
      data.evidence_relevance_score
    );


  const relevanceStatus =
    data.evidence_relevance_status ??
    'unknown';


  // ==========================================================
  // Availability
  // ==========================================================

  const modernAvailable =
    modern !== null;

  const traditionalAvailable =
    traditional !== null;

  const relevanceAvailable =
    relevance !== null;


  // ==========================================================
  // Defaults
  // ==========================================================

  let evidenceCategory =
    'unclassified';

  let categoryReason =
    'Available evidence is insufficient for classification.';


  // ==========================================================
  // CASE 1:
  // Modern evidence is available
  //
  // EMA / traditional support may be present OR missing.
  // ==========================================================

  if (
    modernAvailable &&
    relevanceAvailable
  ) {


    // --------------------------------------------------------
    // ESTABLISHED
    // --------------------------------------------------------

    if (
      modern >= 0.60 &&
      relevance >= 0.70
    ) {

      evidenceCategory =
        'established';


      if (traditionalAvailable) {

        categoryReason =
          'Modern evidence is substantial and overall evidence relevance is high.';

      } else {

        categoryReason =
          'Modern evidence is substantial and meets the established-evidence threshold. EMA/HMPC coverage is unavailable, so the classification is based on the available modern evidence.';
      }
    }


    // --------------------------------------------------------
    // TRADITIONAL
    //
    // Only possible when actual traditional/regulatory
    // support exists.
    // Missing EMA can NEVER trigger this category.
    // --------------------------------------------------------

    else if (
      traditionalAvailable &&
      traditional >= 0.75 &&
      modern < 0.40
    ) {

      evidenceCategory =
        'traditional';

      categoryReason =
        'Traditional or regulatory support is strong, while modern evidence remains limited.';
    }


    // --------------------------------------------------------
    // EMERGING
    // --------------------------------------------------------

    else if (
      modern >= 0.40
    ) {

      evidenceCategory =
        'emerging';


      if (traditionalAvailable) {

        categoryReason =
          'Modern evidence is present but does not yet meet the threshold for established evidence.';

      } else {

        categoryReason =
          'Modern evidence is present but does not yet meet the threshold for established evidence. EMA/HMPC coverage is unavailable.';
      }
    }


    // --------------------------------------------------------
    // EVIDENCE GAP
    // --------------------------------------------------------

    else {

      evidenceCategory =
        'evidence_gap';


      if (traditionalAvailable) {

        categoryReason =
          'Current evidence does not meet thresholds for established, traditional, or emerging evidence.';

      } else {

        categoryReason =
          'Modern evidence remains limited and EMA/HMPC coverage is unavailable. Missing regulatory coverage is not interpreted as negative evidence.';
      }
    }
  }


  // ==========================================================
  // CASE 2:
  // No modern score, but strong documented traditional support
  //
  // Allows a clearly traditional profile without pretending
  // that missing modern evidence equals zero.
  // ==========================================================

  else if (
    !modernAvailable &&
    traditionalAvailable &&
    traditional >= 0.75
  ) {

    evidenceCategory =
      'traditional';

    categoryReason =
      'Strong traditional or regulatory support is documented, while a usable modern evidence score is unavailable.';
  }


  // ==========================================================
  // Output
  // ==========================================================

  return {

    json: {

      ...data,

      evidence_category:
        evidenceCategory,

      evidence_category_reason:
        categoryReason,

      evidence_category_coverage: {
        modern_evidence_available:
          modernAvailable,

        traditional_support_available:
          traditionalAvailable,

        evidence_relevance_available:
          relevanceAvailable,

        evidence_relevance_status:
          relevanceStatus
      },

      evidence_category_version:
        'phythera_evidence_category_v2',

      scoring_version:
        'phythera_scoring_v2',

      last_scored_at:
        new Date().toISOString()
    }
  };
});

const profile =
  $('Update Evidence Category').first().json;

return [
  {
    json: {
      plant_id:
        profile.plant_id,

      indication_id:
        profile.indication_id,

      source_convergence_score:
        null,

      source_convergence_status:
        "not_available",

      source_convergence_reason:
        "No validated cross-cultural mapping is available for this plant.",

      source_convergence_score_version:
        "phythera_source_convergence_v1"
    }
  }
];

// ============================================================
// Calculate Source Convergence Score
// Version: phythera_source_convergence_v1
//
// Scoring:
// strong_overlap        -> 1.00
// partial_overlap       -> 0.60
// distinct_concepts     -> 0.00
// no_meaningful_mapping -> 0.00
//
// IMPORTANT:
// If a mapping run contains more than one European indication,
// this v1 scorer returns null rather than assigning the wrong
// plant-indication score.
// ============================================================

const items = $input.all();


// ============================================================
// Helpers
// ============================================================

function parseProfile(value) {
  if (!value) return {};

  if (typeof value === "object") {
    return value;
  }

  if (typeof value === "string") {
    try {
      return JSON.parse(value);
    } catch {
      return {};
    }
  }

  return {};
}


function normalize(value) {
  return String(value ?? "")
    .trim()
    .toLowerCase();
}


// ============================================================
// Select newest usable mapping run
// ============================================================

const runs = items
  .map(item => ({
    row: item.json,
    profile: parseProfile(item.json.profile_json)
  }))
  .filter(({ row }) =>
    row.id &&
    row.mapping_version === "phythera_crosscultural_v1"
  )
  .sort((a, b) =>
    new Date(b.row.created_at ?? 0) -
    new Date(a.row.created_at ?? 0)
  );

let selected = null;

for (const run of runs) {
  const status =
    normalize(run.row.validation_status);

  if (
    status === "pass" ||
    status === "warning"
  ) {
    selected = run;
    break;
  }
}


// ============================================================
// No usable mapping run
// ============================================================

if (!selected) {
  const profile =
    $("Update Evidence Category").first().json;

  return [
    {
      json: {
        plant_id:
          profile.plant_id,

        indication_id:
          profile.indication_id,

        source_convergence_score:
          null,

        source_convergence_status:
          "not_available",

        source_convergence_reason:
          "No usable validated cross-cultural mapping was available.",

        mapping_run_id:
          null,

        source_convergence_score_version:
          "phythera_source_convergence_v1"
      }
    }
  ];
}


// ============================================================
// Inspect mapping structure
// ============================================================

const row = selected.row;
const profile = selected.profile;

const mappings =
  Array.isArray(profile.mappings)
    ? profile.mappings
    : [];


// ============================================================
// Determine how many European indications occur
// ============================================================

const europeanIndicationIds =
  new Set(
    mappings
      .map(mapping =>
        mapping
          ?.european_indication
          ?.indication_id
      )
      .filter(Boolean)
  );


// ============================================================
// Safety guard
// ============================================================

if (europeanIndicationIds.size > 1) {
  const dbProfile =
    $("Update Evidence Category").first().json;

  return [
    {
      json: {
        plant_id:
          dbProfile.plant_id,

        indication_id:
          dbProfile.indication_id,

        source_convergence_score:
          null,

        source_convergence_status:
          "ambiguous_mapping_scope",

        source_convergence_reason:
          "The mapping run contains multiple European indications and cannot yet be assigned safely to one plant-indication profile.",

        mapping_run_id:
          row.id,

        european_indication_count:
          europeanIndicationIds.size,

        source_convergence_score_version:
          "phythera_source_convergence_v1"
      }
    }
  ];
}


// ============================================================
// Identify strongest valid mapping
// ============================================================

let strongest =
  profile.strongest_convergence ?? null;


// Fallback if strongest_convergence is absent
if (!strongest && mappings.length > 0) {

  const categoryPriority = {
    strong_overlap: 3,
    partial_overlap: 2,
    distinct_concepts: 1,
    no_meaningful_mapping: 0
  };

  const validMappings =
    mappings.filter(mapping => {
      const status =
        normalize(
          mapping.validation_status
        );

      return (
        !status ||
        status === "pass"
      );
    });

  strongest =
    [...validMappings].sort((a, b) => {

      const priorityA =
        categoryPriority[
          a.mapping_category
        ] ?? -1;

      const priorityB =
        categoryPriority[
          b.mapping_category
        ] ?? -1;

      if (priorityA !== priorityB) {
        return priorityB - priorityA;
      }

      return (
        Number(b.confidence ?? 0) -
        Number(a.confidence ?? 0)
      );
    })[0] ?? null;
}


// ============================================================
// No valid comparison
// ============================================================

if (!strongest) {
  const dbProfile =
    $("Update Evidence Category").first().json;

  return [
    {
      json: {
        plant_id:
          dbProfile.plant_id,

        indication_id:
          dbProfile.indication_id,

        source_convergence_score:
          0,

        source_convergence_status:
          "mapped_no_convergence",

        source_convergence_reason:
          "Cross-cultural mapping was performed, but no meaningful convergence was identified.",

        mapping_run_id:
          row.id,

        source_convergence_score_version:
          "phythera_source_convergence_v1"
      }
    }
  ];
}


// ============================================================
// Score category
// ============================================================

const category =
  strongest.mapping_category;

const scoreMap = {
  strong_overlap: 1.0,
  partial_overlap: 0.6,
  distinct_concepts: 0.0,
  no_meaningful_mapping: 0.0
};

const score =
  category in scoreMap
    ? scoreMap[category]
    : null;


// ============================================================
// Build output
// ============================================================

const dbProfile =
  $("Update Evidence Category").first().json;

return [
  {
    json: {
      plant_id:
        dbProfile.plant_id,

      indication_id:
        dbProfile.indication_id,

      source_convergence_score:
        score,

      source_convergence_status:
        score === null
          ? "unclassified"
          : "available",

      source_convergence_reason:
        strongest.convergence_claim ??
        strongest.semantic_overlap ??
        null,

      mapping_category:
        category ?? null,

      mapping_confidence:
        strongest.confidence ?? null,

      european_indication:
        strongest
          ?.european_indication
          ?.source_wording ?? null,

      traditional_indication:
        strongest
          ?.tcm_indication
          ?.source_wording ?? null,

      shared_concept:
        strongest
          ?.mapping_basis
          ?.shared_concept ?? null,

      mapping_run_id:
        row.id,

      source_convergence_score_version:
        "phythera_source_convergence_v1"
    }
  }
];

// ============================================================
// Classify Research Opportunity
// Version: phythera_research_opportunity_v2
//
// IMPORTANT:
// Missing EMA / traditional support or missing convergence
// are NOT interpreted as negative signals.
//
// "none" is only assigned when weak modern evidence exists
// AND the relevant supporting dimensions are actually available
// AND do not show a positive signal.
// ============================================================

const items = $input.all();


// ============================================================
// Helper
// ============================================================

function toScore(value) {

  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const n = Number(value);

  if (
    !Number.isFinite(n) ||
    n < 0 ||
    n > 1
  ) {
    return null;
  }

  return n;
}


// ============================================================
// Classification
// ============================================================

return items.map(item => {

  const data = item.json;

  const modern =
    toScore(
      data.modern_evidence_score
    );

  const traditional =
    toScore(
      data.traditional_support_score
    );

  const relevance =
    toScore(
      data.evidence_relevance_score
    );

  const convergence =
    toScore(
      data.source_convergence_score
    );


  // ==========================================================
  // Availability
  // ==========================================================

  const modernAvailable =
    modern !== null;

  const traditionalAvailable =
    traditional !== null;

  const relevanceAvailable =
    relevance !== null;

  const convergenceAvailable =
    convergence !== null;


  // ==========================================================
  // Positive supporting signals
  // ==========================================================

  const strongTraditionalSignal =
    traditionalAvailable &&
    traditional >= 0.75;

  const strongConvergenceSignal =
    convergenceAvailable &&
    convergence >= 0.60;

  const positiveResearchSignal =
    strongTraditionalSignal ||
    strongConvergenceSignal;


  // ==========================================================
  // Defaults
  // ==========================================================

  let opportunity =
    'unclassified';

  let reason =
    'Available evidence is insufficient to classify the research opportunity.';


  // ==========================================================
  // CASE 1:
  // Modern evidence available
  // ==========================================================

  if (modernAvailable) {


    // --------------------------------------------------------
    // HIGH
    //
    // Weak modern evidence + actual positive historical /
    // regulatory / cross-cultural signal
    // --------------------------------------------------------

    if (
      modern < 0.40 &&
      positiveResearchSignal
    ) {

      opportunity =
        'high';

      reason =
        'Modern evidence remains limited despite strong traditional, regulatory, or cross-cultural support, creating a clear evidence gap worth investigating.';
    }


    // --------------------------------------------------------
    // NONE
    //
    // Only when supporting dimensions have actually been
    // evaluated and show no positive signal.
    //
    // Missing EMA or mapping data can NEVER trigger "none".
    // --------------------------------------------------------

    else if (
      modern < 0.40 &&
      traditionalAvailable &&
      convergenceAvailable &&
      !positiveResearchSignal
    ) {

      opportunity =
        'none';

      reason =
        'Modern evidence is limited and the available traditional and cross-cultural evidence does not currently provide a strong signal for prioritizing further investigation.';
    }


    // --------------------------------------------------------
    // MODERATE
    //
    // Weak modern evidence, but one or more supporting
    // dimensions are missing.
    //
    // We do not interpret missing coverage as a negative signal.
    // --------------------------------------------------------

    else if (
      modern < 0.40
    ) {

      opportunity =
        'moderate';

      reason =
        'Modern evidence remains limited, while one or more traditional, regulatory, or cross-cultural evidence dimensions are unavailable. Missing source coverage is not interpreted as a negative research signal.';
    }


    // --------------------------------------------------------
    // MODERATE
    //
    // Emerging modern evidence
    // --------------------------------------------------------

    else if (
      modern < 0.60
    ) {

      opportunity =
        'moderate';

      reason =
        'Modern evidence is present but remains incomplete, leaving meaningful scope for additional clinical research.';
    }


    // --------------------------------------------------------
    // MODERATE
    //
    // Strong modern evidence + cross-cultural convergence
    // --------------------------------------------------------

    else if (
      strongConvergenceSignal
    ) {

      opportunity =
        'moderate';

      reason =
        'Modern evidence is substantial, but cross-cultural convergence provides an additional rationale for comparative or confirmatory research.';
    }


    // --------------------------------------------------------
    // LOW
    //
    // Strong modern evidence with high relevance.
    //
    // This remains valid even when EMA is missing because
    // evidence_relevance_v2 transparently marks coverage
    // as partial.
    // --------------------------------------------------------

    else if (
      modern >= 0.60 &&
      relevanceAvailable &&
      relevance >= 0.70
    ) {

      opportunity =
        'low';

      reason =
        traditionalAvailable
          ? 'Modern and overall evidence are already substantial, so the remaining research opportunity is comparatively limited.'
          : 'Modern evidence is already substantial. EMA/HMPC coverage is unavailable, but the available evidence indicates a comparatively limited remaining clinical research opportunity.';
    }


    // --------------------------------------------------------
    // Remaining intermediate cases
    // --------------------------------------------------------

    else {

      opportunity =
        'moderate';

      reason =
        'Evidence is meaningful but not sufficiently established to classify the remaining research opportunity as low.';
    }
  }


  // ==========================================================
  // CASE 2:
  // No usable modern evidence score
  // ==========================================================

  else if (positiveResearchSignal) {

    opportunity =
      'high';

    reason =
      'A strong traditional, regulatory, or cross-cultural signal is present, while a usable modern clinical evidence score is unavailable, representing a substantial research opportunity.';
  }


  // ==========================================================
  // Output
  // ==========================================================

  return {

    json: {

      ...data,

      research_opportunity:
        opportunity,

      research_opportunity_reason:
        reason,

      research_opportunity_coverage: {

        modern_evidence_available:
          modernAvailable,

        traditional_support_available:
          traditionalAvailable,

        evidence_relevance_available:
          relevanceAvailable,

        source_convergence_available:
          convergenceAvailable
      },

      research_opportunity_version:
        'phythera_research_opportunity_v2'
    }
  };
});

// ============================================================
// Build Profile Rationale
// Version: phythera_profile_rationale_v2
//
// Handles complete and partial evidence coverage.
// Missing source coverage is explicitly distinguished
// from negative evidence.
// ============================================================

const items = $input.all();


// ============================================================
// Helpers
// ============================================================

function toScore(value) {

  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const n = Number(value);

  return Number.isFinite(n)
    ? n
    : null;
}


function formatScore(value) {

  return value === null
    ? null
    : value.toFixed(3);
}


// ============================================================
// Build rationale
// ============================================================

return items.map(item => {

  const data =
    item.json;


  const modern =
    toScore(
      data.modern_evidence_score
    );

  const traditional =
    toScore(
      data.traditional_support_score
    );

  const relevance =
    toScore(
      data.evidence_relevance_score
    );

  const convergence =
    toScore(
      data.source_convergence_score
    );


  const relevanceStatus =
    data.evidence_relevance_status ??
    'unknown';


  const category =
    data.evidence_category ??
    'unclassified';

  const opportunity =
    data.research_opportunity ??
    'unclassified';


  // ==========================================================
  // Evidence category
  // ==========================================================

  const categoryText = {

    established:
      'The evidence profile is classified as established.',

    traditional:
      'The evidence profile is primarily supported by traditional or regulatory use.',

    emerging:
      'The evidence profile is classified as emerging.',

    evidence_gap:
      'The evidence profile currently shows a substantial evidence gap.',

    unclassified:
      'The evidence profile cannot yet be fully classified.'

  }[category] ??
  'The evidence profile cannot yet be fully classified.';


  // ==========================================================
  // Evidence relevance
  // ==========================================================

  let scoreText =
    'No usable overall evidence relevance score is currently available.';


  // ----------------------------------------------------------
  // Complete coverage
  // ----------------------------------------------------------

  if (
    relevance !== null &&
    modern !== null &&
    traditional !== null
  ) {

    scoreText =
      `Overall evidence relevance is ${formatScore(relevance)}, ` +
      `combining modern clinical evidence (${formatScore(modern)}) ` +
      `with traditional or regulatory support (${formatScore(traditional)}).`;
  }


  // ----------------------------------------------------------
  // Partial coverage:
  // modern available, EMA/traditional support missing
  // ----------------------------------------------------------

  else if (
    relevance !== null &&
    modern !== null &&
    traditional === null
  ) {

    scoreText =
      `Overall evidence relevance is ${formatScore(relevance)} based on ` +
      `available modern clinical evidence (${formatScore(modern)}). ` +
      `EMA/HMPC traditional or regulatory coverage is unavailable and ` +
      `is therefore not interpreted as negative evidence.`;
  }


  // ----------------------------------------------------------
  // Partial coverage:
  // traditional available, modern missing
  // ----------------------------------------------------------

  else if (
    relevance !== null &&
    modern === null &&
    traditional !== null
  ) {

    scoreText =
      `Overall evidence relevance is ${formatScore(relevance)} based on ` +
      `available traditional or regulatory support (${formatScore(traditional)}). ` +
      `A usable modern clinical evidence score is currently unavailable.`;
  }


  // ==========================================================
  // Source convergence
  // ==========================================================

  let convergenceText =
    'No cross-cultural source-convergence score is currently available.';


  if (convergence !== null) {

    convergenceText =
      `Cross-cultural source convergence is ${formatScore(convergence)}.`;

  } else {

    const hasEMA =
      Boolean(
        $('Pick Next Plant')
          .first()
          .json
          .ema_source_url
      );

    const hasTraditionalSource =
      Boolean(
        $('Pick Next Plant')
          .first()
          .json
          .traditional_source_url
      );


    if (
      hasTraditionalSource &&
      !hasEMA
    ) {

      convergenceText =
        'Cross-cultural source convergence could not be calculated because no EMA/HMPC comparison source is available.';

    } else if (
      !hasTraditionalSource
    ) {

      convergenceText =
        'Cross-cultural source convergence could not be calculated because no traditional comparison source is available.';
    }
  }


  // ==========================================================
  // Research opportunity
  // ==========================================================

  const opportunityText =
    opportunity === 'unclassified'
      ? 'The remaining research opportunity cannot yet be classified.'
      : `The remaining research opportunity is classified as ${opportunity}.`;


  // ==========================================================
  // Coverage transparency
  // ==========================================================

  const coverageText =
    relevanceStatus === 'partial'
      ? 'The evidence relevance score is based on partial source coverage.'
      : relevanceStatus === 'complete'
        ? 'The evidence relevance score is based on complete configured source coverage.'
        : null;


  // ==========================================================
  // Final rationale
  // ==========================================================

  const profileRationale = [

    categoryText,

    scoreText,

    convergenceText,

    opportunityText,

    coverageText

  ]
    .filter(Boolean)
    .join(' ');


  // ==========================================================
  // Output
  // ==========================================================

  return {

    json: {

      ...data,

      profile_rationale:
        profileRationale,

      scoring_version:
        'phythera_scoring_v2',

      last_scored_at:
        new Date().toISOString(),

      profile_rationale_version:
        'phythera_profile_rationale_v2'
    }
  };
});

const q = $('Pick Next Plant').first().json;

return [
  {
    json: {
      queue_id: q.id,
      plant_id: q.plant_id,
      scientific_name: q.scientific_name,
      target_indication: q.target_indication,
      indication_context: q.indication_context,

      traditional_source_url:
        q.traditional_source_url,

      traditional_system:
        q.traditional_system,

      modules:
        q.modules
    }
  }
];

const q = $('Pick Next Plant').first().json;
const policy = $('Check TCM Source Policy').first().json;

return [
  {
    json: {
      queue_id: q.id,
      plant_id: q.plant_id,
      scientific_name: q.scientific_name,
      target_indication: q.target_indication,
      indication_context: q.indication_context,

      traditional_source_url: q.traditional_source_url,
      traditional_system: q.traditional_system,

      source_policy_checked: true,
      automated_retrieval_authorized:
        policy.tcm_automated_retrieval_allowed === true,
      tcm_source_policy_status:
        policy.tcm_source_policy_status ?? null,
      tcm_source_policy_version:
        policy.tcm_source_policy_version ?? null,

      modules: q.modules,
      priority: q.priority
    }
  }
];

const data = $json;

return [
  {
    json: {
      ...data,

      traditional_support_score: null,

      traditional_support_level:
        'unavailable',

      traditional_support_basis:
        'No EMA/HMPC source is available for this plant and indication.',

      traditional_support_reason:
        'EMA/HMPC coverage is unavailable. Missing database coverage is not interpreted as negative evidence.',

      ema_extraction_run_id:
        null,

      ema_validation_status:
        null,

      traditional_support_score_version:
        'phythera_traditional_support_v2'
    }
  }
];

// ============================================================
// Check TCM Source Policy
// Version: phythera_tcm_source_policy_v2
//
// PUBLIC RELEASE POLICY:
//
// Automated retrieval is disabled by default.
// A source must be explicitly approved before machine access
// and reuse are permitted.
// ============================================================

const data = $json;

const q =
  $('Pick Next Plant').first().json;


// ------------------------------------------------------------
// Helper
// ------------------------------------------------------------

function parseObject(value) {

  if (!value) return {};

  if (typeof value === 'object') {
    return value;
  }

  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch {
      return {};
    }
  }

  return {};
}


// ------------------------------------------------------------
// Source metadata
// ------------------------------------------------------------

const metadata =
  parseObject(q.metadata);

const sourcePolicy =
  parseObject(
    metadata.tcm_source_policy
  );

const sourceUrl =
  q.traditional_source_url ??
  data.traditional_source_url ??
  null;


let hostname = null;

try {

  hostname =
    sourceUrl
      ? new URL(sourceUrl).hostname.toLowerCase()
      : null;

} catch {

  hostname = null;
}


// ------------------------------------------------------------
// Explicit allow only
// ------------------------------------------------------------

const explicitlyAllowed =
  sourcePolicy.automated_retrieval_allowed === true;


let policyStatus;
let policyReason;


if (explicitlyAllowed) {

  policyStatus =
    'allowed_explicit';

  policyReason =
    sourcePolicy.basis ??
    'Automated retrieval and reuse have been explicitly approved for this source.';

} else {

  policyStatus =
    'review_required';

  policyReason =
    'Automated retrieval is disabled unless source terms or permissions explicitly allow machine access and reuse.';
}


// ------------------------------------------------------------
// Output
// ------------------------------------------------------------

return [
  {
    json: {

      ...data,

      traditional_source_url:
        sourceUrl,

      tcm_source_hostname:
        hostname,

      tcm_automated_retrieval_allowed:
        explicitlyAllowed,

      tcm_source_policy_status:
        policyStatus,

      tcm_source_policy_reason:
        policyReason,

      tcm_source_policy_version:
        'phythera_tcm_source_policy_v2'
    }
  }
];
